# owner: platform
import unittest

from hourglass.models import Span
from hourglass.gaps import uncovered_gaps

class UncoveredGapsTests(unittest.TestCase):
    def test_gap_between_two_spans(self):
        worked = [Span(540, 720), Span(780, 1020)]
        self.assertEqual(
            uncovered_gaps(worked, Span(540, 1020)),
            ["gap 12:00-13:00 (60 min)"]
        )

    def test_gaps_at_both_ends_of_opening_hours(self):
        worked = [Span(600, 900)]
        self.assertEqual(
            uncovered_gaps(worked, Span(540, 1020)),
            [
                "gap 09:00-10:00 (60 min)",
                "gap 15:00-17:00 (120 min)"
            ]
        )

    def test_nothing_worked_is_one_gap(self):
        self.assertEqual(
            uncovered_gaps([], Span(540, 1020)),
            ["gap 09:00-17:00 (480 min)"]
        )

    def test_fully_covered_has_no_gaps(self):
        worked = [Span(540, 720), Span(720, 1020)]
        self.assertEqual(
            uncovered_gaps(worked, Span(540, 1020)), []
        )

    def test_overlapping_spans_leave_no_gap(self):
        worked = [Span(540, 800), Span(700, 1020)]
        self.assertEqual(
            uncovered_gaps(worked, Span(540, 1020)), []
        )

    def test_span_before_opening_raises(self):
        worked = [Span(480, 600)]
        with self.assertRaises(ValueError):
            uncovered_gaps(worked, Span(540, 1020))

    def test_span_past_closing_raises(self):
        worked = [Span(900, 1080)]
        with self.assertRaises(ValueError):
            uncovered_gaps(worked, Span(540, 1020))
